codec_error <- function(kind) stop(structure(
    list(message=kind,call=NULL,kind=kind),
    class=c("jpeg_decode_error","error","condition")
))
new_bit_writer <- function() list2env(
    list(data=integer(),buffer=0L,pending=0L,padding_bits=0L,stuffed_bytes=0L),
    parent=emptyenv()
)
write_bits <- function(writer,value,width) {
  if (width == 0L) return(invisible(NULL))
  for (shift in seq.int(width-1L,0L)) {
    writer$buffer <- 2L*writer$buffer+bitwAnd(bitwShiftR(as.integer(value),shift),1L)
    writer$pending <- writer$pending+1L
    if (writer$pending == 8L) {
      writer$data <- c(writer$data,writer$buffer)
      if (writer$buffer == 255L) {
        writer$data <- c(writer$data,0L)
        writer$stuffed_bytes <- writer$stuffed_bytes+1L
      }
      writer$buffer <- writer$pending <- 0L
    }
  }
}
pad_bits <- function(writer) {
  if (writer$pending != 0L) {
    width <- 8L-writer$pending
    writer$padding_bits <- writer$padding_bits+width
    write_bits(writer,power2(width)-1L,width)
  }
}
restart <- function(writer,number) {
  pad_bits(writer)
  writer$data <- c(writer$data,255L,208L+number %% 8L)
}
new_bit_reader <- function(data,position) list2env(
    list(data=data,position=position,buffer=0L,remaining=0L),
    parent=emptyenv()
)
read_bit <- function(reader) {
  if (reader$remaining == 0L) {
    value <- reader$data[reader$position+1L]
    if (value == 255L) {
      if (reader$data[reader$position+2L] != 0L) codec_error("marker")
      reader$position <- reader$position+2L
    } else reader$position <- reader$position+1L
    reader$buffer <- value
    reader$remaining <- 8L
  }
  reader$remaining <- reader$remaining-1L
  bitwAnd(bitwShiftR(reader$buffer,reader$remaining),1L)
}
read_bits <- function(reader,width) {
  value <- 0L
  for (unused in seq_len(width)) value <- 2L*value+read_bit(reader)
  value
}
discard_bits <- function(reader) {
  reader$buffer <- reader$remaining <- 0L
}
find_resync <- function(data,position) {
  for (offset in seq.int(
      position,
      length(data)-2L
  )) if (data[offset+1L] == 255L && ((data[offset+2L] >= 208L && data[offset+2L] <= 215L) || data[offset+2L] == 217L)) return(offset)
  stop("missing resynchronization marker")
}

clamp_byte <- function(value) min(max(value,0),255)
to_ycbcr <- function(pixel) {
  r <- pixel[1L]
  g <- pixel[2L]
  b <- pixel[3L]
  c(
      (19595*r+38470*g+7471*b+32768) %/% 65536,
      (-11059*r-21709*g+32768*b+8421375) %/% 65536,
      (32768*r-27439*g-5329*b+8421375) %/% 65536
  )
}
to_rgb <- function(y,cb,cr) {
  c(
      clamp_byte(y+(91881*(cr-128)+32768) %/% 65536),
      clamp_byte(y+(-22554*(cb-128)-46802*(cr-128)+32768) %/% 65536),
      clamp_byte(y+(116130*(cb-128)+32768) %/% 65536)
  )
}
split_planes <- function(image) {
  height <- dim(image)[1L]
  width <- dim(image)[2L]
  planes <- lapply(1:3,function(unused) matrix(0,height,width))
  for (y in seq_len(height)) for (x in seq_len(width)) {
    values <- to_ycbcr(image[y,x,])
    for (k in 1:3) planes[[k]][y,x] <- values[k]
  }
  planes
}
component_planes <- function(planes,factors,mx,my) {
  height <- nrow(planes[[1L]])
  width <- ncol(planes[[1L]])
  hmax <- max(vapply(factors,function(f) f[1L],integer(1)))
  vmax <- max(vapply(factors,function(f) f[2L],integer(1)))
  result <- list()
  for (k in seq_along(planes)) {
    h <- factors[[k]][1L]
    v <- factors[[k]][2L]
    fx <- hmax %/% h
    fy <- vmax %/% v
    component <- matrix(0,8L*v*my,8L*h*mx)
    for (y in 0:(nrow(component)-1L)) for (x in 0:(ncol(component)-1L)) {
      total <- 0
      for (j in 0:(fy-1L)) for (i in 0:(fx-1L)) total <- total+planes[[k]][
          min(fy*y+j,height-1L)+1L,
          min(fx*x+i,width-1L)+1L
      ]
      component[y+1L,x+1L] <- total %/% (fx*fy)
    }
    result[[k]] <- component
  }
  result
}
upsample <- function(planes,factors,width,height) {
  hmax <- max(vapply(factors,function(f) f[1L],integer(1)))
  vmax <- max(vapply(factors,function(f) f[2L],integer(1)))
  lapply(seq_along(planes),function(k) {
    plane <- matrix(0,height,width)
    for (y in 0:(height-1L)) for (x in 0:(width-1L)) plane[y+1L,x+1L] <- planes[[k]][
        (y*factors[[k]][2L]) %/% vmax+1L,
        (x*factors[[k]][1L]) %/% hmax+1L
    ]
    plane
  })
}
combine_rgb <- function(planes) {
  image <- array(0,c(nrow(planes[[1L]]),ncol(planes[[1L]]),3L))
  for (y in seq_len(dim(image)[1L])) for (x in seq_len(dim(image)[2L])) image[y,x,] <- to_rgb(
      planes[[1L]][y,x],
      planes[[2L]][y,x],
      planes[[3L]][y,x]
  )
  image
}

ZIGZAG <- do.call(rbind,lapply(1:8,function(u) cbind(u,1:8)))
ZIGZAG <- ZIGZAG[
    order(rowSums(ZIGZAG),ifelse(rowSums(ZIGZAG) %% 2L == 1L,ZIGZAG[,1L],-ZIGZAG[,1L])),
    ,
    drop=FALSE
]
rounded_shift <- function(value,shift) (value+power2(shift-1L)) %/% power2(shift)
forward_dct <- function(block,transform) {
  intermediate <- result <- matrix(0,8L,8L)
  for (u in 1:8) for (x in 1:8) {
    total <- 0
    for (y in 1:8) total <- total+transform[u,y]*(block[y,x]-128)
    intermediate[u,x] <- rounded_shift(total,11L)
  }
  for (u in 1:8) for (v in 1:8) {
    total <- 0
    for (x in 1:8) total <- total+intermediate[u,x]*transform[v,x]
    result[u,v] <- rounded_shift(total,15L)
  }
  result
}
inverse_dct <- function(coefficients,transform) {
  intermediate <- result <- matrix(0,8L,8L)
  for (y in 1:8) for (v in 1:8) {
    total <- 0
    for (u in 1:8) total <- total+transform[u,y]*coefficients[u,v]
    intermediate[y,v] <- rounded_shift(total,11L)
  }
  for (y in 1:8) for (x in 1:8) {
    total <- 0
    for (v in 1:8) total <- total+intermediate[y,v]*transform[v,x]
    result[y,x] <- clamp_byte(rounded_shift(total,15L)+128)
  }
  result
}
quantization_tables <- function(basic,quality) {
  scale <- if (quality < 50L) 5000L %/% quality else 200L-2L*quality
  setNames(lapply(basic,function(table) pmin(pmax((table*scale+50L) %/% 100L,1L),255L)),c("0","1"))
}
quantize <- function(values,table) sign(values)*((abs(values)+table %/% 2L) %/% table)
zigzag <- function(values) values[ZIGZAG]
unzigzag <- function(sequence) {
  result <- matrix(0,8L,8L)
  result[ZIGZAG] <- sequence
  result
}
dequantize <- function(sequence,table,keep=64L) {
  result <- matrix(0,8L,8L)
  positions <- ZIGZAG[seq_len(keep),,drop=FALSE]
  result[positions] <- sequence[seq_len(keep)]*table[positions]
  result
}

TABLE_KEYS <- list(c(0L,0L),c(1L,0L),c(0L,1L),c(1L,1L))
TABLE_NAMES <- c("dc_luma","ac_luma","dc_chroma","ac_chroma")
table_key <- function(class,id) paste(class,id,sep=",")
power2 <- function(n) bitwShiftL(1L,n)
category <- function(value) {
  n <- 0L
  magnitude <- abs(value)
  while (magnitude != 0) {
    n <- n+1L
    magnitude <- magnitude %/% 2L
  }
  n
}
extra_bits <- function(value) {
  n <- category(value)
  c(if (value >= 0) value else value+power2(n)-1L,n)
}
amplitude <- function(bits,n) if (n == 0L) 0 else if (bits >= power2(n-1L)) bits else bits-power2(n)+1L
new_huffman <- function(counts,symbols) {
  codes <- list()
  decode <- new.env(hash=TRUE,parent=emptyenv())
  code <- offset <- 0L
  for (length in seq_len(16L)) {
    for (i in seq_len(counts[length])) {
      symbol <- symbols[offset+i]
      codes[[as.character(symbol)]] <- c(length,code)
      assign(table_key(length,code),symbol,decode)
      code <- code+1L
    }
    offset <- offset+counts[length]
    code <- 2L*code
  }
  list(counts=counts,symbols=symbols,codes=codes,decode=decode)
}
optimized_table <- function(frequencies) {
  frequencies <- c(frequencies,1L)
  sizes <- others <- integer(257L)
  repeat {
    available <- which(frequencies > 0L)
    if (length(available) < 2L) break
    available <- available[order(frequencies[available],-available)]
    first <- available[1L]
    second <- available[2L]
    frequencies[first] <- frequencies[first]+frequencies[second]
    frequencies[second] <- 0L
    sizes[first] <- sizes[first]+1L
    while (others[first] != 0L) {
      first <- others[first]
      sizes[first] <- sizes[first]+1L
    }
    others[first] <- second
    sizes[second] <- sizes[second]+1L
    while (others[second] != 0L) {
      second <- others[second]
      sizes[second] <- sizes[second]+1L
    }
  }
  counts <- integer(257L)
  for (size in sizes) if (size > 0L) counts[size] <- counts[size]+1L
  if (max(sizes) >= 17L) for (length in seq.int(max(sizes),17L)) while (counts[length] > 0L) {
    shorter <- length-2L
    while (counts[shorter] == 0L) shorter <- shorter-1L
    counts[length] <- counts[length]-2L
    counts[length-1L] <- counts[length-1L]+1L
    counts[shorter+1L] <- counts[shorter+1L]+2L
    counts[shorter] <- counts[shorter]-1L
  }
  longest <- max(which(counts[1:16] > 0L))
  counts[longest] <- counts[longest]-1L
  indices <- which(sizes[1:256] > 0L)
  symbols <- indices[order(sizes[indices],indices)]-1L
  new_huffman(counts[1:16],symbols)
}

read_ppm <- function(path) {
  lines <- readLines(path)
  dimensions <- as.integer(strsplit(lines[2L]," ",fixed=TRUE)[[1L]])
  image <- array(0,c(dimensions[2L],dimensions[1L],3L))
  for (y in seq_len(dimensions[2L])) {
    values <- as.numeric(strsplit(lines[y+3L]," ",fixed=TRUE)[[1L]])
    for (x in seq_len(dimensions[1L])) image[y,x,] <- values[seq.int(3L*x-2L,3L*x)]
  }
  image
}
write_ppm <- function(path,image) {
  lines <- c("P3",paste(dim(image)[2L],dim(image)[1L]),"255")
  for (y in seq_len(dim(image)[1L])) {
    values <- unlist(lapply(seq_len(dim(image)[2L]),function(x) image[y,x,]),use.names=FALSE)
    lines <- c(lines,paste(sprintf("%.0f",values),collapse=" "))
  }
  writeLines(lines,path,useBytes=TRUE)
}
read_params <- function(path) {
  params <- list()
  for (line in readLines(path)) {
    words <- strsplit(line," ",fixed=TRUE)[[1L]]
    name <- words[1L]
    params[[name]] <- if (name %in% c("sampling","huffman")) words[2L] else if (name %in% c(
        "qualities",
        "truncate"
    )) as.integer(words[-1L]) else as.integer(words[2L])
  }
  params
}
read_tables <- function(path) {
  lines <- readLines(path)
  matrix_at <- function(start) do.call(
      rbind,
      lapply(lines[seq.int(start,start+7L)],function(line) as.numeric(strsplit(line," ",fixed=TRUE)[[1L]]))
  )
  tables <- list()
  for (start in seq.int(28L,37L,3L)) {
    words <- strsplit(lines[start]," ",fixed=TRUE)[[1L]]
    tables[[table_key(words[2L],words[3L])]] <- new_huffman(
        as.integer(strsplit(lines[start+1L]," ",fixed=TRUE)[[1L]]),
        as.integer(strsplit(lines[start+2L]," ",fixed=TRUE)[[1L]])
    )
  }
  list(transform=matrix_at(2L),basic=list(matrix_at(11L),matrix_at(20L)),standard=tables)
}
read_hex <- function(path) {
  text <- paste(readLines(path),collapse="")
  starts <- seq.int(1L,nchar(text),2L)
  strtoi(substring(text,starts,starts+1L),base=16L)
}
write_hex <- function(path,data) {
  lines <- character()
  for (start in seq.int(1L,length(data),32L)) lines <- c(
      lines,
      paste(sprintf("%02x",as.integer(data[seq.int(start,min(start+31L,length(data)))])),collapse="")
  )
  writeLines(lines,path,useBytes=TRUE)
}
